import {destinations,mapsUrl,embedUrl,homeOrigin} from './maps.mjs?v=2.8.1';
import {localDateKey,defaultAppliedDate,buildTrendStats,appliedDateInput,submittedAppliedDate} from './stats.mjs?v=2.8.1';
const $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const I=(name)=>{const paths={radar:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/><path d="m12 12 8-8"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12h18M10 12v3h4v-3"/>',radio:'<circle cx="12" cy="12" r="2"/><path d="M7 7a7 7 0 0 0 0 10M17 7a7 7 0 0 1 0 10M4 4a11 11 0 0 0 0 16M20 4a11 11 0 0 1 0 16"/>',file:'<path d="M5 2h9l5 5v15H5zM14 2v6h5M8 12h8M8 16h8"/>',profile:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6"/>',refresh:'<path d="M20 7a9 9 0 1 0 1 9M20 2v6h-6"/>',arrow:'<path d="M6 18 18 6M6 6h12v12"/>',x:'<path d="m5 5 14 14M5 19 19 5"/>',pin:'<path d="M12 22s8-8 8-13a8 8 0 0 0-16 0c0 5 8 13 8 13z"/><circle cx="12" cy="9" r="3"/>',check:'<path d="m4 12 5 5 11-11"/>',download:'<path d="M12 2v13m-5-5 5 5 5-5M4 17v5h16v-5"/>',plus:'<path d="M12 4v16M4 12h16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>'};return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.file}</svg>`};
let state={jobs:[],applications:[],documents:[],drafts:[],sources:[],profile:{},search:{},queue:{}},tab=0,selected=null,drafts=[],draftId=null,query='',where='',work='all',board='all',maxApplicants='',unknownApplicants=true,showInactive=false,sort='relevance';
let chartDays=14,searchPending=false,lastSearchTime='';
let appliedFilters={query:'',where:'',work:'all',board:'all',maxApplicants:'',unknownApplicants:true,showInactive:false,sort:'relevance'};
let token=sessionStorage.getItem('radar-dev-token')||'',busy=false,loading=true;
const titles=['Discover jobs','Saved jobs','Applications','Sources','Documents','Profile','Search settings','Users'];
const icons=['search','bookmark','briefcase','radio','file','profile','settings','profile'];
const date=n=>n?new Date(n*1000).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Not set';
const ago=n=>!n?'Never':Date.now()/1000-n<3600?'Just now':Math.floor((Date.now()/1000-n)/3600)+'h ago';
const appFor=j=>state.applications.find(a=>a.job_id===j.id)||{status:'new',notes:''};
const score=j=>state.search.keywords?.toLowerCase().split(/\s+/).reduce((s,k)=>s+(j.title.toLowerCase().includes(k)?5:0),0)||0;
const sourceName=id=>state.sources.find(s=>s.id===id)?.name||id;
const opts=(items,current)=>items.map(([value,label])=>`<option value="${esc(value)}" ${value===current?'selected':''}>${esc(label)}</option>`).join('');
function toast(s,error=false){const t=$('#toast');t.textContent=s;t.className=error?'visible bad':'visible';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',8000)}
async function api(path,options={}){const headers={...(token?{Authorization:'Bearer '+token}:{}),...options.headers};if(options.body&&!(options.body instanceof FormData))headers['Content-Type']='application/json';const r=await fetch('/api'+path,{...options,headers});if(!r.ok){let message;try{message=(await r.json()).detail}catch{message='Request failed'}if(r.status===401)throw Error('Authentication required. Open your configured Radar address through Cloudflare Access. For local development only, use the session-token box below.');throw Error(typeof message==='string'?message:JSON.stringify(message))}return r.status===204?null:r.json()}
async function refresh(){try{const next=await api('/workspace');if(state.identity?.email&&state.identity.email!==next.identity?.email){selected=null;drafts=[];draftId=null;memberList=[];$('#overlay').innerHTML='';}state=next;loading=false;render()}catch(e){state={jobs:[],applications:[],documents:[],drafts:[],sources:[],profile:{},search:{},queue:{}};selected=null;drafts=[];draftId=null;memberList=[];$('#overlay').innerHTML='';loading=false;render();$('#page').innerHTML=`<div class="empty"><h2>Open your private workspace</h2><p>${esc(e.message)}</p><p>Cloudflare Access protects the hosted address. Local development uses a session token.</p><form id="dev-login"><label>Local development token<input type="password" name="token" autocomplete="off" required></label><button class="primary">Open local workspace</button></form></div>`}}
function filtered(){const {query,where,work,board,maxApplicants,unknownApplicants,showInactive,sort}=appliedFilters;return state.jobs.filter(j=>{const a=appFor(j);return (tab===1?a.status==='saved':tab===2?['applied','interviewing','rejected','offer','withdrawn'].includes(a.status):a.status!=='hidden'&&(j.active||showInactive))&&query.toLowerCase().split(/\s+/).every(q=>(j.title+' '+j.company+' '+j.description).toLowerCase().includes(q))&&(!where||j.location.toLowerCase().includes(where.toLowerCase()))&&(work==='all'||j.workplace===work)&&(board==='all'||j.source===board)&&(!maxApplicants||(j.applicants==null?unknownApplicants:j.applicants<=Number(maxApplicants)))}).sort((a,b)=>sort==='relevance'?score(b)-score(a)||b.firstSeen-a.firstSeen:sort==='applicants'?(a.applicants??Infinity)-(b.applicants??Infinity):b.firstSeen-a.firstSeen)}
function render(){
 const due=state.applications.filter(a=>a.status==='applied'&&a.followup&&a.followup<Date.now()/1000);
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a href="/" class="brand"><span class="brand-icon">${I('radar')}</span><span>D3V<span class="brand-sub">JOB RADAR</span></span></a><div class="workspace-label">YOUR WORKSPACE</div><nav>${titles.map((t,i)=>i===7&&!state.identity?.isOwner?'':`<button class="nav ${tab===i?'active':''}" data-tab="${i}" title="${t}">${I(icons[i])}<span>${t}</span>${i===2&&due.length?`<span class="nav-count">${due.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-profile"><span class="eyebrow">BUILT AROUND YOU</span><h3>Your next IT role.<br>A little less searching.</h3><p>Discover. Prepare. Apply.<br>Keep the conversation moving.</p><span class="location-pill">${I('pin')} ${esc(state.profile.location||'Set your location')}</span></div><div class="sidebar-bottom"><span class="avatar">DR</span><div><strong>${esc(state.profile.name||'Your workspace')}</strong><span>Private · Homelab edition</span></div><span class="online-dot"></span></div></aside><main><header class="topbar"><span class="crumb">Workspace › <strong>${titles[tab]}</strong></span><span class="private" title="${esc(state.identity?.email||'')}"><span class="online-dot"></span> ${esc(state.identity?.email==='local'?'Local workspace':state.identity?.email||'Your homelab · Your data')}${state.identity?.mode==='cloudflare'?' · <a href="/cdn-cgi/access/logout">Sign out</a>':''}</span></header><div class="content"><div class="heading"><div><div class="eyebrow">LESS SEARCHING. MORE POSSIBILITIES.</div><h1>${['Find your next chapter.','Keep the good ones close.','Your next move, in motion.','A wider view of opportunity.','Your experience. Ready to adapt.','One profile. Fewer repeat questions.','Make your radar work for you.','Invite your beta testers.'][tab]}</h1><p>${['Find roles, prepare a focused application, and track what happens next.','Your shortlist, ready when you are.','Every application, document version, and follow-up in one place.','Automatic feeds, indexed discovery, and direct board searches.','Upload your base documents. Review the text once. Tailor them for each role.','Your own answers, saved privately and ready for recognized application questions.','Choose what to search for and how to prepare your application drafts.','Manage approved sign-in emails and keep each workspace private.'][tab]}</p></div><div class="heading-actions"><button class="secondary" data-action="import">${I('plus')} Import job</button><button class="primary" data-action="scan" ${state.scanRunning?'disabled':''}>${I('refresh')} ${state.scanRunning?'Scanning…':'Scan sources'}</button></div></div><div class="stats"><div><span class="stat-label">ACTIVE OPPORTUNITIES ${I('search')}</span><strong>${state.jobs.filter(j=>j.active).length}</strong><span>Listings and imported opportunities</span></div><div><span class="stat-label">APPLICATIONS SENT ${I('briefcase')}</span><strong>${state.applications.filter(a=>a.applied).length.toString().padStart(2,'0')}</strong><span>Your applications stay saved</span></div><div><span class="stat-label">FOLLOW-UPS DUE ${I('clock')}</span><strong>${due.length.toString().padStart(2,'0')}</strong><span>Letters drafted when you need them</span></div><div><span class="stat-label">BASE DOCUMENTS ${I('file')}</span><strong>${state.documents.filter(d=>d.active).length}<small> / 2</small></strong><span>Resume + cover-letter template</span></div></div>${state.identity?.privateWorkspace&&!state.documents.length?'<div class="banner">Your private beta workspace · Review Profile answers and upload your own resume to get started. Your documents and applications are separate from other users.</div>':''}<div id="dashboard-stats"></div><div id="page"></div><footer><span>${I('radar')} D3V JOB RADAR · HOMELAB EDITION <span class="footer-credit">· vibe coded by <a href="https://www.d3vsolutions.com" target="_blank" rel="noopener noreferrer">d3vsolutions.com</a></span></span><span>${state.scheduler?'12-hour background collection enabled':'Background collection disabled'} · ${state.queue.pending||0} drafts queued</span></footer></div></main></div>`;
 if(tab===0)renderStatistics();
 if(tab<=2)renderFeed();else if(tab===3)renderSources();else if(tab===4)renderDocuments();else if(tab===5)renderProfile();else if(tab===6)renderSettings();else if(state.identity?.isOwner)renderUsers();else{tab=0;render();}
}
function renderFeed(){const jobs=filtered();$('#page').innerHTML=`<div class="feed-header"><div class="feed-tabs"><button class="selected">${tab===0?'Opportunities':titles[tab]} <span>${jobs.length}</span></button></div><div class="feed-tools"><button class="text-button" data-action="export">${I('download')} Export CSV</button></div></div><form id="discover-search-form" class="filters" aria-label="Search collected jobs"><label class="search-box">${I('search')}<input id="query" aria-label="Job title, company, or skill" placeholder="Search title, company, or skill…" value="${esc(query)}"></label><input id="where" class="filter-input" placeholder="Location contains…" value="${esc(where)}"><select id="work" aria-label="Workplace">${opts([['all','Any workplace'],['remote','Remote'],['hybrid','Hybrid'],['onsite','On-site'],['unknown','Unknown']],work)}</select><select id="board" aria-label="Source">${opts([['all','All sources'],...state.sources.slice().sort((a,b)=>a.name.localeCompare(b.name,undefined,{sensitivity:'base'})).map(s=>[s.id,s.name]),['manual','Manual']],board)}</select><button class="primary search-submit" type="submit">${I('search')} Search jobs</button></form><p id="search-status" class="search-feedback" role="status" aria-live="polite">${searchPending?'Filters changed — press Search jobs.':lastSearchTime?'Search complete · '+filtered().length+' matches · '+esc(lastSearchTime):'Search filters collected listings. Use Scan sources to fetch new listings.'}</p><div class="extra-filters"><label class="applicant-limit">Maximum reported applicants <input id="applicant-max" type="number" min="0" placeholder="Any" value="${esc(maxApplicants)}"></label><label class="inline-check"><input id="unknown-applicants" type="checkbox" ${unknownApplicants?'checked':''}> Include unknown counts</label><label class="inline-check"><input id="inactive" type="checkbox" ${showInactive?'checked':''}> Include inactive jobs</label><label class="sort-label">Sort <select id="sort">${opts([['relevance','Relevance'],['newest','Recently discovered'],['applicants','Lowest known applicant count']],sort)}</select></label></div><div class="results-bar"><span><b id="result-count">${jobs.length}</b> opportunities <span class="muted">· Counts are source-reported, approximate, or unknown</span></span><button class="text-button" data-action="clear">Reset filters</button></div><div class="job-list" id="job-list">${jobCards(jobs)}</div>`}
function jobCards(jobs){return jobs.length?jobs.slice(0,150).map(j=>{const a=appFor(j);const due=a.status==='applied'&&a.followup&&a.followup<Date.now()/1000;return `<article class="job-card"><div class="job-main"><span class="company-icon color-${j.company.charCodeAt(0)%4}">${esc(j.company.slice(0,2).toUpperCase())}</span><div class="job-info"><div class="company-name">${esc(j.company)} <span>·</span> ${esc(sourceName(j.source))}</div><button class="job-title" data-open="${esc(j.id)}">${esc(j.title)}</button><div class="job-meta"><span>${I('pin')}${esc(j.location)}</span><span>${esc(j.salary||'Salary not listed')}</span><span>${j.applicants==null?'Applicants unknown':esc(j.applicantLabel)+': '+j.applicants}</span></div><div class="job-tags"><span>${esc(j.workplace)}</span><span>${esc(a.status)}</span>${!j.verified?'<span class="status-tag">Needs full description</span>':''}${!j.active?'<span>Inactive listing</span>':''}${due?'<span class="due-tag">Follow-up due</span>':''}${state.drafts.some(d=>d.job_id===j.id&&d.kind==='resume')?'<span class="match">Application drafts ready</span>':''}</div></div></div><div class="job-actions"><button class="icon-button ${a.status==='saved'?'bookmarked':''}" data-save="${esc(j.id)}" aria-label="Save job" ${!['new','saved'].includes(a.status)?'disabled':''}>${I('bookmark')}</button><span class="date">Found ${date(j.firstSeen)}</span><button class="view-button" data-map="${esc(j.id)}">Map & commute</button><button class="view-button" data-open="${esc(j.id)}">Open role ${I('arrow')}</button></div></article>`}).join('')+(jobs.length>150?'<p class="limit-note">Showing 150 matches. Narrow your filters or export all matches.</p>':''):`<div class="empty"><span class="empty-icon">${I('radar')}</span><h3>${loading?'Loading your workspace…':'No roles in this view yet.'}</h3><p>Scan your sources, import a job from a required board, or adjust your filters.</p><button class="secondary" data-action="import">Import a job</button></div>`}
function updateList(){if(!$('#job-list'))return;const jobs=filtered();$('#job-list').innerHTML=jobCards(jobs);$('#result-count').textContent=jobs.length}
function renderSources(){$('#page').innerHTML=`<div class="section-title"><div><h2>Your source network</h2><p>Your original boards and new sources are included. Each source shows its current access mode.</p></div><span class="badge">${state.indexedSearch?'Indexed discovery configured':'Indexed discovery needs an API key'}</span></div><label class="source-directory-search">Filter sources<input id="source-filter" placeholder="Search source name, collection mode, or application support…" aria-label="Filter sources"></label><p class="small-note">${state.sources.length} sources · Public feed/API where verified; indexed discovery requires your Brave key. Website availability does not establish an application integration.</p><div class="sources-grid">${state.sources.map(s=>`<section class="source-card" data-source-card><div class="source-top"><span class="company-icon">${esc(s.name.slice(0,2))}</span><span class="health ${s.error?'warning':s.success?'':'neutral'}">${s.error?'Needs attention':s.success?'Last scan succeeded':s.automatic?'Ready to scan':'Search + import'}</span></div><h3>${esc(s.name)}</h3><p>${esc(s.about||(s.mode==='indexed'?'Indexed discovery with optional Brave Search key; manual import always available':s.mode==='mcp'?'Official MCP search interface':s.mode==='ashby'?'Public employer Ashby feed':'Public job feed'))}</p><p class="small-note">${s.photoNumber?'Image #'+s.photoNumber+' · ':''}${s.review?.status?'Website check: HTTP '+s.review.status:s.review?.error?'Website check unavailable ('+esc(s.review.error)+')':'Website check not recorded'}${s.review?.finalUrl&&s.review.finalUrl!==s.url?' · Redirect destination: '+esc(s.review.finalUrl):''}</p><div class="source-application"><strong>${s.application?.mode==='conditional'?'In-Radar form: job-dependent':s.application?.mode==='unverified'?'External: integration unverified':'External application'}</strong><p>${esc(s.application?.reason||'Check the job application options.')}</p>${s.application?.documentation?`<a href="${esc(s.application.documentation)}" target="_blank" rel="noreferrer">Application documentation ${I('arrow')}</a>`:''}</div><div class="source-metrics"><span><b>${s.count||0}</b> last collected</span><span>${ago(s.checked)}</span></div>${s.error?`<p class="source-error">${esc(s.error)}</p>`:''}<div class="source-links"><a href="${esc(s.searchUrl)}" target="_blank" rel="noreferrer">Open search ${I('arrow')}</a><a href="${esc(s.url)}" target="_blank" rel="noreferrer">Visit board ${I('arrow')}</a></div></section>`).join('')}</div><div class="roadmap">${I('radio')}<div><h3>A source can be included without pretending it has an open feed.</h3><p>Indexed results are discovery leads, not verified current vacancies. Paste the full description before tailoring. LinkedIn applicant counts may represent interest or apply clicks; preserve the label you saw and do not treat unknown as zero. Dice results are retrieved through an AI-oriented search interface; verify details on Dice and the employer’s page.</p></div></div>`}
function renderDocuments(){$('#page').innerHTML=`<div class="documents-grid">${[['resume','Base resume','Your factual work history and skills. PDF, DOCX, or TXT.'],['cover','Base cover letter','Use {{company}} and {{role}} to tailor your own wording.']].map(([kind,title,desc])=>`<section class="source-card upload-card"><div class="source-top"><span class="company-icon">${I('file')}</span><span class="health">${state.documents.some(d=>d.kind===kind&&d.active)?'Active document ready':'Upload to get started'}</span></div><h2>${title}</h2><p>${desc} Maximum 8 MB.</p><form class="upload-form" data-kind="${kind}"><input type="file" name="file" accept=".pdf,.docx,.txt" required aria-label="Upload ${title}"><button class="primary">Upload ${kind==='resume'?'resume':'cover letter'}</button></form></section>`).join('')}</div><div class="section-title"><div><h2>Your document versions</h2><p>Original uploads and extracted text are encrypted. Check the extracted text before preparing applications.</p></div></div><div class="version-list">${state.documents.map(d=>`<div class="version-row"><span class="company-icon">${I('file')}</span><div><strong>${esc(d.name)}</strong><p>${d.kind==='resume'?'Resume':'Cover letter'} · Uploaded ${date(d.created)} ${d.active?'· Active':''}</p></div><button class="secondary" data-document="${d.id}">Review text</button>${!d.active?`<button class="text-button" data-activate="${d.id}">Make active</button>`:''}<button class="text-button" data-original="${d.id}">Original ${I('download')}</button></div>`).join('')||'<div class="empty"><h3>Your base documents go here.</h3><p>Upload once, then create separate, job-specific versions from any role.</p></div>'}</div><div class="roadmap">${I('check')}<div><h3>Factual tailoring, with visible evidence.</h3><p>Resumes keep your original experience, dates, and qualifications. Relevant skills already present in your resume are highlighted, and existing adjacent bullets can be reordered. Missing skills appear in the gap report and are never added as claims. Cover letters use your placeholder template or an evidence-based draft. No ATS pass is guaranteed.</p></div></div>`}
function renderProfile(){const p=state.profile;const booleans=[['veteran','Veteran status'],['disability','Disability status'],['needs_sponsorship','Visa sponsorship required now or in future'],['felony','Felony conviction history'],['us_citizen','US citizen'],['authorized_us','Legally authorized to work in the US']];$('#page').innerHTML=`<form id="profile-form" class="settings-card"><div class="section-title"><div><h2>Your application profile</h2><p>Review every answer before exporting. These private answers stay out of generated resumes and cover letters.</p></div><span class="badge">Encrypted at rest</span></div><div class="form-grid"><label>Full name<input name="name" value="${esc(p.name)}" required></label><label>Email<input name="email" type="email" value="${esc(p.email)}"></label><label>Home location<input name="location" value="${esc(p.location)}"></label><label>Home address for directions<input name="home_address" autocomplete="street-address" maxlength="300" value="${esc(p.home_address||'')}" placeholder="Street address, city, state, ZIP"></label><p class="small-note">Used automatically for Directions from home. Stored encrypted, kept out of resumes and letters, and shared with Google only when you open a route. A ZIP or city gives an approximate starting point.</p></div><h3>Standard application questions</h3><div class="answer-grid">${booleans.map(([k,label])=>`<label>${label}<select name="${k}">${opts([['false','No'],['true','Yes']],String(p[k]))}</select></label>`).join('')}</div><div class="form-actions"><button class="primary">Save profile</button><button type="button" class="secondary" data-action="answers">Export answers for form helper ${I('download')}</button></div><p class="small-note">The helper fills recognized select/radio/yes-no fields when you click it. Different question wording, conditional questions, attestations, and submit buttons remain untouched. You can review the filled answers before continuing.</p></form><section class="roadmap">${I('profile')}<div><h3>Use your answers on application forms.</h3><p>Install the included Chrome extension from the extension folder as an unpacked extension. Import your answer pack in its popup, open an application, and click Fill recognized questions. The answer pack stays in browser session storage until the browser closes; Clear answers removes it sooner.</p></div></section>`}
function renderSettings(){const s=state.search;$('#page').innerHTML=`<form id="settings-form" class="settings-card"><div class="section-title"><div><h2>Your saved search</h2><p>Used by source connectors and automatic document preparation.</p></div><span class="badge">Every 12 hours</span></div><div class="form-grid"><label>Job keywords<input name="keywords" value="${esc(s.keywords)}" required maxlength="150"></label><label>Search location<input name="location" value="${esc(s.location)}"></label><label>Workplace<select name="workplace">${opts([['all','Any'],['remote','Remote'],['hybrid','Hybrid'],['onsite','On-site']],s.workplace)}</select></label><label>Follow up after days<input name="followup_days" type="number" min="1" max="90" value="${s.followup_days||7}"></label></div><label class="check-line"><input name="auto_prepare" type="checkbox" ${s.auto_prepare?'checked':''}> Automatically prepare documents for matching new jobs when a base resume is active</label><p class="small-note">Preparation runs in a persistent queue. New draft versions are created when the resume, template, job description, or contact details change. Source refreshes keep a 12-hour cooldown.</p><button class="primary">Save search settings</button></form><div class="settings-card"><h2>Bring your existing jobs with you</h2><p>Import the migration JSON included with this package. Existing applications and notes are retained when present in the export.</p><form id="migration-form"><input type="file" name="file" accept=".json" required><button class="secondary">Import previous workspace</button></form></div><div class="settings-card"><h2>Connected services</h2><p>Cloudflare Access validates your identity. Optional Brave indexed search is configured with BRAVE_SEARCH_API_KEY in the server’s .env file. No AI provider or paid API is needed for factual resume and cover-letter tailoring.</p></div>`}
function modal(title,body,wide=false){$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><div><span class="eyebrow">YOUR APPLICATION WORKSPACE</span><h2>${esc(title)}</h2></div><button class="icon-button" data-action="close" aria-label="Close dialog">${I('x')}</button></header>${body}</section></div>`;$('#overlay').querySelector('button')?.focus()}
async function openJob(id){selected=state.jobs.find(j=>j.id===id);if(!selected)return;drafts=(await api('/jobs/'+encodeURIComponent(id)+'/drafts')).drafts;draftId=drafts[0]?.id;renderJob()}
function renderJob(){const j=selected,a=appFor(j),draft=drafts.find(d=>d.id===draftId);modal(j.title,`<div class="role-summary"><div><strong>${esc(j.company)}</strong><span>${esc(j.location)} · ${esc(j.workplace)}</span></div><a href="${esc(j.url)}" target="_blank" rel="noreferrer" class="primary">View on ${esc(sourceName(j.source))} ${I('arrow')}</a>${j.companyUrl&&j.companyUrl.startsWith('https://')?`<a href="${esc(j.companyUrl)}" target="_blank" rel="noreferrer" class="secondary">Employer page ${I('arrow')}</a>`:''}</div>${!j.active?'<div class="banner error">This listing is inactive. Your application history is retained.</div>':''}${j.source==='dice'?'<p class="small-note">These listings were retrieved using AI-assisted search. Review the full job details on Dice and the employer’s page before applying.</p>':''}${mapPanel(j)}<section class="apply-panel" id="apply-panel"><h3>Apply for this job</h3><p>Check whether the employer supports an application form inside Radar.</p><button type="button" class="primary" data-action="apply-check">Check application options</button></section><div class="role-columns"><div><form id="application-form"><label>Application status<select name="status" id="application-status">${opts(['new','saved','applied','interviewing','rejected','offer','withdrawn','hidden'].map(s=>[s,s[0].toUpperCase()+s.slice(1)]),a.status)}</select></label><label>Applied date<input name="applied" id="applied-date" type="date" value="${appliedDateInput(a.applied)}"></label><p class="small-note">Change this date if you applied on a different day.</p><label>Follow-up date<input name="followup" type="date" value="${a.followup?localDateKey(new Date(a.followup*1000)):''}"></label><label>Your notes<textarea name="notes" rows="4" placeholder="Recruiter, interview details, next steps…">${esc(a.notes)}</textarea></label><p class="small-note">Applied ${date(a.applied)} · Follow-up ${date(a.followup)}</p><button class="secondary">Save application</button></form><h3>Job description</h3><div class="description job-description">${esc(j.description||'No description available.')}</div><div class="form-actions"><button class="text-button" data-action="edit-job">Edit job / applicant count</button>${j.source==='dice'&&!j.verified?'<button class="secondary" data-action="full-description">Load full Dice description</button>':''}</div></div><div class="draft-panel"><div class="section-title"><div><h3>Application documents</h3><p>Separate versions for this exact role.</p></div></div><div class="form-actions"><button class="primary" data-action="prepare">Prepare resume + cover letter</button><button class="secondary" data-action="followup">Draft follow-up</button></div>${drafts.length?`<label class="draft-select">Version<select id="draft-select">${drafts.map(d=>`<option value="${d.id}" ${d.id===draftId?'selected':''}>${d.kind==='cover'?'Cover letter':d.kind==='followup'?'Follow-up':'Resume'} · ${date(d.created)} ${d.approved?'· Reviewed':''}</option>`).join('')}</select></label><form id="draft-form"><label>Draft text<textarea name="text" class="draft-editor" spellcheck="true">${esc(draft?.text||'')}</textarea></label><label class="check-line"><input name="reviewed" type="checkbox" ${draft?.reviewed?'checked':''}> I reviewed this version</label><div class="form-actions"><button class="secondary">Save edits</button>${['docx','pdf','txt'].map(format=>`<button type="button" class="text-button" data-download="${format}">${format.toUpperCase()} ${I('download')}</button>`).join('')}</div></form>${draft?.report?`<div class="match-box"><h4>Keyword coverage ${draft.report.coverage==null?'not scored':draft.report.coverage+'%'}</h4><p class="small-note">${esc(draft.report.label)}</p><p><strong>Supported:</strong> ${esc(draft.report.matched.join(', ')||'No matched terms')}</p><p><strong>Not in source resume:</strong> ${esc(draft.report.missing.join(', ')||'No missing terms identified')}</p></div>`:''}<p class="small-note">${esc(draft?.mode)}</p>`:'<div class="empty draft-empty"><h3>Ready for a more focused application?</h3><p>Upload a base resume, then prepare documents for this role. All source facts are preserved.</p></div>'}</div></div>`,true)}
function importModal(job=null){modal(job?'Edit job details':'Import a job',`<form id="job-form" data-id="${esc(job?.id||'')}"><p class="small-note">Paste the individual job URL to automatically fetch available details. Fetch details, review the fields, add notes, and save here. The job will be bookmarked in Saved jobs. You can also enter details manually.</p><div class="import-url-row"><label>Job URL<input type="url" name="url" id="import-job-url" value="${esc(job?.url)}" required placeholder="https://…"></label><div class="import-fetch"><button type="button" class="secondary" data-action="fetch-import">Fetch job details</button><p id="import-fetch-status" role="status" aria-live="polite">Details stay in this dialog. Review them, then click Save to Saved jobs.</p></div></div><div class="form-grid"><label>Job title<input name="title" value="${esc(job?.title)}" required></label><label>Company<input name="company" value="${esc(job?.company)}" required></label><label>Source<select name="source">${opts([['manual','Manual'],...state.sources.slice().sort((a,b)=>a.name.localeCompare(b.name,undefined,{sensitivity:'base'})).map(s=>[s.id,s.name])],job?.source||'manual')}</select></label><label>Location<input name="location" value="${esc(job?.location)}"></label><label>Office address for Maps (optional)<input name="officeAddress" maxlength="300" value="${esc(job?.officeAddress||'')}" placeholder="Verified office street address"></label><label>Workplace<select name="workplace">${opts([['unknown','Unknown'],['remote','Remote'],['hybrid','Hybrid'],['onsite','On-site']],job?.workplace||'unknown')}</select></label><label>Salary as listed<input name="salary" value="${esc(job?.salary)}"></label><label>Applicant count<input name="applicants" type="number" min="0" value="${job?.applicants??''}" placeholder="Leave blank if unknown"></label><label>Count label<select name="applicantLabel">${opts([['Not supplied','Not supplied'],['Reported applicants','Reported applicants'],['Approximate / apply interest','Approximate / apply interest'],['At least','At least'],['Over','Over']],job?.applicantLabel||'Not supplied')}</select></label></div><label>Full job description<textarea name="description" rows="10" minlength="80" required>${esc(job?.description)}</textarea></label>${!job?'<label>Your notes (optional)<textarea name="notes" rows="3" maxlength="20000" placeholder="Why this role interests you, a contact, or what to review later…"></textarea></label><p class="small-note">Saved jobs keeps this role and your notes for later. Saving does not submit an application.</p>':''}<button class="primary">${job?'Save job details':'Save to Saved jobs'}</button></form>`,true)}
async function openDocument(id){const d=await api('/documents/'+id);modal('Review '+d.name,`<form id="document-form" data-id="${id}"><p class="small-note">Review text extracted from your original file. Edits affect future drafts; the original upload is preserved. Cover-letter placeholders: {{company}}, {{role}}, {{name}}, {{relevant_skills}}, {{evidence}}.</p><label>Source text<textarea name="text" class="draft-editor">${esc(d.text)}</textarea></label><button class="primary">Save source text</button></form>`)}
async function download(path,name){const r=await fetch('/api'+path,{headers:token?{Authorization:'Bearer '+token}:{}});if(!r.ok)throw Error('Download failed');const blob=await r.blob();saveBlob(blob,name)}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCsv(){const rows=[['Title','Company','Location','Source','Status','Applied','Follow up','Applicant count','Count label','URL'],...filtered().map(j=>{const a=appFor(j);return [j.title,j.company,j.location,j.source,a.status,date(a.applied),date(a.followup),j.applicants??'',j.applicantLabel,j.url]})];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"').join(',')).join('\r\n');saveBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),'job-radar.csv')}
async function run(action){if(busy)return;busy=true;try{await action()}catch(e){toast(e.message,true)}finally{busy=false}}
document.addEventListener('click',event=>{const target=event.target.closest('button,a');if(!target||!['tab','open','save','document','activate','original','download','action','chartDays','map'].some(k=>k in target.dataset))return;run(async()=>{if(target.dataset.map){const j=state.jobs.find(j=>j.id===target.dataset.map);if(j)modal('Location & commute',mapPanel(j),true);return}if(target.dataset.chartDays){chartDays=Number(target.dataset.chartDays);renderStatistics();return}if(target.dataset.tab!=null){tab=Number(target.dataset.tab);render();return}if(target.dataset.open){await openJob(target.dataset.open);return}if(target.dataset.save){const j=state.jobs.find(j=>j.id===target.dataset.save),a=appFor(j);await api('/applications/'+encodeURIComponent(j.id),{method:'PUT',body:JSON.stringify({...a,status:a.status==='saved'?'new':'saved'})});await refresh();return}if(target.dataset.document){await openDocument(target.dataset.document);return}if(target.dataset.activate){await api('/documents/'+target.dataset.activate+'/activate',{method:'POST'});await refresh();return}if(target.dataset.original){const d=state.documents.find(x=>x.id===target.dataset.original);await download('/documents/'+d.id+'/original',d.name);return}if(target.dataset.download){await saveDraft();await download('/drafts/'+draftId+'/download?format='+target.dataset.download,selected.company+'-'+drafts.find(d=>d.id===draftId).kind+'.'+target.dataset.download);return}switch(target.dataset.action){case 'map-view':showJobMap(target,false);break;case 'map-route':showJobMap(target,true);break;case 'fetch-import':await fetchImportDetails();break;case 'apply-check':await showApplyOptions();break;case 'apply-load':loadApplicationEmbed();break;case 'apply-submitted':confirmApplicationSubmission();break;case 'close':$('#overlay').innerHTML='';break;case 'scan':await api('/scan',{method:'POST'});state.scanRunning=true;render();toast('Collection started. Source status will update as each board finishes.');break;case 'import':importModal();break;case 'edit-job':importModal(selected);break;case 'prepare':toast('Preparing factual, job-specific drafts…');await api('/jobs/'+encodeURIComponent(selected.id)+'/prepare',{method:'POST'});await refresh();await openJob(selected.id);break;case 'followup':const d=await api('/jobs/'+encodeURIComponent(selected.id)+'/followup',{method:'POST'});drafts=(await api('/jobs/'+encodeURIComponent(selected.id)+'/drafts')).drafts;draftId=d.id;renderJob();break;case 'full-description':const result=await api('/jobs/'+encodeURIComponent(selected.id)+'/details',{method:'POST'});await refresh();await openJob(result.job.id);break;case 'answers':saveBlob(new Blob([JSON.stringify(await api('/profile/answers'),null,2)],{type:'application/json'}),'radar-answer-pack.json');toast('Answer pack exported. Import it in the extension popup.');break;case 'clear':query=where=maxApplicants='';work=board='all';unknownApplicants=true;showInactive=false;appliedFilters={query,where,work,board,maxApplicants,unknownApplicants,showInactive,sort};searchPending=false;lastSearchTime='';renderFeed();break;case 'export':exportCsv();break}})});
document.addEventListener('input',e=>{if(e.target.id==='source-filter'){const q=e.target.value.toLowerCase();document.querySelectorAll('[data-source-card]').forEach(card=>card.hidden=!card.textContent.toLowerCase().includes(q));return}if(e.target.id==='applied-date'){delete e.target.dataset.autoFilled;return}if(e.target.id==='query')query=e.target.value;else if(e.target.id==='where')where=e.target.value;else if(e.target.id==='applicant-max')maxApplicants=e.target.value;else return;markSearchPending()});
document.addEventListener('change',e=>{const v=e.target.value;switch(e.target.id){case 'work':work=v;break;case 'board':board=v;break;case 'sort':sort=v;break;case 'unknown-applicants':unknownApplicants=e.target.checked;break;case 'inactive':showInactive=e.target.checked;break;case 'application-status':{const input=$('#applied-date'),existing=selected?appFor(selected).applied:null;if(input&&!input.value)input.value=defaultAppliedDate(v,input.value,existing);return}case 'draft-select':if($('#draft-form')?.elements.text.value!==drafts.find(d=>d.id===draftId)?.text&&!confirm('Discard unsaved draft edits?')){e.target.value=draftId;return}draftId=v;renderJob();return;default:return}markSearchPending()});
async function saveDraft(){const form=$('#draft-form');if(!form)return;const value={text:form.elements.text.value,reviewed:form.elements.reviewed.checked};await api('/drafts/'+draftId,{method:'PUT',body:JSON.stringify(value)});Object.assign(drafts.find(d=>d.id===draftId),value)}
document.addEventListener('submit',e=>{e.preventDefault();run(async()=>{const f=e.target,values=Object.fromEntries(new FormData(f));if(f.id==='discover-search-form'){await applySearch();return}if(f.id==='member-invite-form'){await api('/admin/users',{method:'POST',body:JSON.stringify({email:values.email})});await renderUsers();toast('Radar access added. Add this email to your Cloudflare Access Allow policy.');return}else if(f.id==='dev-login'){token=values.token;sessionStorage.setItem('radar-dev-token',token);await refresh();return}if(f.classList.contains('upload-form')){const data=new FormData(f);data.append('kind',f.dataset.kind);const d=await api('/documents',{method:'POST',body:data});await refresh();await openDocument(d.id);toast('Uploaded. Review the extracted text before preparing applications.');return}if(f.id==='profile-form'){for(const k of ['veteran','disability','needs_sponsorship','felony','us_citizen','authorized_us'])values[k]=values[k]==='true';await api('/profile',{method:'PUT',body:JSON.stringify(values)})}else if(f.id==='settings-form'){values.auto_prepare=f.elements.auto_prepare.checked;values.followup_days=Number(values.followup_days);await api('/search',{method:'PUT',body:JSON.stringify(values)});await api('/scan',{method:'POST'})}else if(f.id==='job-form'){values.applicants=values.applicants===''?null:Number(values.applicants);const id=f.dataset.id;if(!id)values.save_to_saved=true;const data=await api('/jobs'+(id?'/'+encodeURIComponent(id):''),{method:id?'PUT':'POST',body:JSON.stringify(values)});$('#overlay').innerHTML='';if(!id){tab=data.savedTo==='applications'?2:1;query=where=maxApplicants='';work=board='all';sort='relevance';unknownApplicants=true;showInactive=false;appliedFilters={query,where,work,board,maxApplicants,unknownApplicants,showInactive,sort};searchPending=false;lastSearchTime='';}await refresh();toast(id?'Job details saved.':data.savedTo==='applications'?'Job updated in Applications. Existing application status was kept.':'Saved to Saved jobs. Open it there whenever you are ready.');return}else if(f.id==='application-form'){const dateValue=submittedAppliedDate(values.status,values.applied,appFor(selected).applied);values.applied=dateValue?new Date(dateValue+'T12:00:00').getTime()/1000:null;values.followup=values.followup?new Date(values.followup+'T12:00:00').getTime()/1000:null;await api('/applications/'+encodeURIComponent(selected.id),{method:'PUT',body:JSON.stringify(values)});await refresh();renderJob();toast('Application saved.');return}else if(f.id==='draft-form'){await saveDraft();toast('Draft edits saved.');return}else if(f.id==='document-form'){await api('/documents/'+f.dataset.id,{method:'PUT',body:JSON.stringify(values)});$('#overlay').innerHTML=''}else if(f.id==='migration-form'){const d=await api('/migrate',{method:'POST',body:new FormData(f)});toast(`Imported ${d.imported} jobs and ${d.applications} application records.`)}await refresh();toast('Saved.');})});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#overlay').innerHTML=''});
render();refresh();setInterval(()=>{if(!busy&&!$('#overlay').innerHTML&&tab<=3&&!$('#source-filter')?.value&&!document.activeElement?.closest('.filters,.extra-filters,.source-directory-search'))refresh()},10000);

function markSearchPending(){searchPending=true;const status=$('#search-status');if(status)status.textContent='Filters changed — press Search jobs.';}
async function applySearch(){
 const button=$('#discover-search-form button[type="submit"]');
 if(button){button.disabled=true;button.textContent='Searching…';}
 const status=$('#search-status');if(status)status.textContent='Searching collected listings…';
 await new Promise(resolve=>requestAnimationFrame(resolve));
 appliedFilters={query,where,work,board,maxApplicants,unknownApplicants,showInactive,sort};
 updateList();searchPending=false;lastSearchTime=new Date().toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'});
 if(status)status.textContent=`Search complete · ${filtered().length} matches · ${lastSearchTime}`;
 if(button){button.disabled=false;button.innerHTML=I('search')+' Search jobs';}
}
function renderStatistics(){
 const host=$('#dashboard-stats');if(!host||tab!==0)return;
 const stats=buildTrendStats(state.jobs,state.applications,chartDays),rows=stats.buckets;
 const width=760,height=190,left=42,right=18,top=18,bottom=36,plotW=width-left-right,plotH=height-top-bottom;
 const peak=Math.max(4,...rows.flatMap(r=>[r.listings,r.applications])),max=Math.ceil(peak/4)*4;
 const x=i=>left+i*plotW/(rows.length-1),y=n=>top+plotH-n*plotH/max;
 const points=key=>rows.map((r,i)=>`${x(i).toFixed(1)},${y(r[key]).toFixed(1)}`).join(' ');
 const grid=Array.from({length:5},(_,i)=>{const n=max*i/4;return `<line x1="${left}" x2="${width-right}" y1="${y(n)}" y2="${y(n)}" stroke="#e6ede8"/><text x="${left-9}" y="${y(n)+4}" text-anchor="end" fill="#84968c" font-size="10">${n}</text>`}).join('');
 const labels=rows.map((r,i)=>i===0||i===rows.length-1||i%Math.ceil(rows.length/5)===0?`<text x="${x(i)}" y="${height-12}" text-anchor="middle" fill="#84968c" font-size="10">${esc(r.label)}</text>`:'').join('');
 const dots=rows.map((r,i)=>`<g><title>${esc(r.label)}: ${r.listings} listings discovered; ${r.applications} applications</title><circle cx="${x(i)}" cy="${y(r.listings)}" r="3" fill="#267957"/><circle cx="${x(i)}" cy="${y(r.applications)}" r="3" fill="#527fa8"/></g>`).join('');
 host.innerHTML=`<section class="activity-panel"><div class="activity-heading"><div><span class="eyebrow">YOUR SEARCH IN NUMBERS</span><h2>Job search activity</h2><p>Listings discovered and applications recorded by date.</p></div><div class="chart-range" role="group" aria-label="Chart date range">${[14,30].map(n=>`<button type="button" data-chart-days="${n}" aria-pressed="${n===chartDays}" class="${n===chartDays?'selected':''}">${n} days</button>`).join('')}</div></div><div class="chart-summary"><span><i class="legend-dot listings"></i><strong>${stats.listings}</strong> listings discovered</span><span><i class="legend-dot applications"></i><strong>${stats.applications}</strong> applications</span></div><svg class="activity-chart" viewBox="0 0 ${width} ${height}" role="img" aria-labelledby="activity-chart-title activity-chart-desc"><title id="activity-chart-title">Job search activity over ${chartDays} days</title><desc id="activity-chart-desc">${stats.listings} listings discovered and ${stats.applications} applications. Each point exposes its daily count.</desc>${grid}<polygon points="${left},${top+plotH} ${points('listings')} ${width-right},${top+plotH}" fill="#e9f4ec"/><polyline points="${points('listings')}" fill="none" stroke="#267957" stroke-width="2.5"/><polyline points="${points('applications')}" fill="none" stroke="#527fa8" stroke-width="2.5"/>${dots}${labels}</svg><p class="chart-note">Based on listings loaded in this workspace and saved application dates.${stats.undatedApplications?' '+stats.undatedApplications+' applications without a date are excluded.':''}</p><details class="chart-data"><summary>View daily counts</summary><table><thead><tr><th>Date</th><th>Listings discovered</th><th>Applications</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.label)}</td><td>${r.listings}</td><td>${r.applications}</td></tr>`).join('')}</tbody></table></details></section>`;
}

let applyOptions=null;
async function showApplyOptions(){
 const host=$('#apply-panel'); if(!host||!selected)return;
 host.innerHTML='<h3>Apply for this job</h3><p role="status">Checking employer application options…</p>';
 const id=selected.id;
 try{
  const result=await api('/jobs/'+encodeURIComponent(id)+'/apply-options');
  if(selected?.id!==id||!$('#apply-panel'))return;
  applyOptions={...result,jobId:id};
  host.innerHTML=`<h3>${result.mode==='embed'?'Apply inside Radar':'Apply on the provider site'}</h3><p role="status">${esc(result.reason)}</p><div class="form-actions">${result.mode==='embed'?'<button type="button" class="primary" data-action="apply-load">Load '+esc(result.provider)+' application</button>':''}<a class="secondary" href="${esc(result.externalUrl)}" target="_blank" rel="noopener noreferrer">Open application externally ${I('arrow')}</a></div><p class="small-note">Loading the form contacts the provider. Radar does not send your stored profile or documents automatically. Upload your reviewed files in the employer form. Nothing is marked Applied until you confirm submission.</p><div id="application-embed"></div><button type="button" class="secondary" data-action="apply-submitted">I submitted this application</button>`;
 }catch(error){host.innerHTML=`<h3>Application options unavailable</h3><p>${esc(error.message)}</p><button class="secondary" data-action="apply-check">Retry check</button>`;}
}
function loadApplicationEmbed(){
 if(!applyOptions||selected?.id!==applyOptions.jobId||applyOptions.mode!=='embed')return;
 const url=new URL(applyOptions.embedUrl);
 if(!['https://job-boards.greenhouse.io','https://jobs.ashbyhq.com'].includes(url.origin))throw Error('Unsupported application provider');
 $('#application-embed').innerHTML=`<p class="small-note">Employer-hosted form · If it is blank or refuses to connect, use Open application externally. Radar cannot inspect cross-site form success. After submitting, use the confirmation button below.</p><iframe class="application-frame" title="${esc(applyOptions.provider)} application for ${esc(selected.title)}" src="${esc(url.href)}" referrerpolicy="origin" sandbox="allow-forms allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox allow-downloads"></iframe>`;
}
function confirmApplicationSubmission(){
 const a=appFor(selected),f=$('#application-form');
 if(!f)return;
 f.elements.status.value='applied';
 f.elements.applied.value=defaultAppliedDate('applied',f.elements.applied.value,a.applied);
 toast('Submission noted. Review the applied date and click Save application to record it.');
 f.scrollIntoView({behavior:'smooth',block:'center'});
}

async function fetchImportDetails(automatic=false){
 const form=$('#job-form');if(!form)return;
 const url=form.elements.url.value.trim(),status=$('#import-fetch-status'),button=form.querySelector('[data-action="fetch-import"]');
 if(!url||!form.elements.url.checkValidity()){status.textContent='Enter a valid HTTPS job URL first.';form.elements.url.focus();return;}
 const fields=['title','company','location','workplace','salary','description'];
 const previous=Object.fromEntries(fields.map(k=>[k,form.elements[k].value]));
 if(!automatic&&fields.some(k=>k==='workplace'?previous[k]!=='unknown':previous[k].trim())&&!confirm('Replace the current job fields with details fetched from this URL? Your current fields stay intact if fetching fails.'))return;
 button.disabled=true;button.textContent='Fetching…';status.textContent='Reading public job page…';
 try{
  const result=await api('/import/fetch',{method:'POST',body:JSON.stringify({url})});
  if($('#job-form')!==form)return;
  if(form.elements.url.value.trim()!==url){status.textContent='URL changed while fetching. Fetch again for the new URL.';return;}
  if(fields.some(k=>form.elements[k].value!==previous[k])){status.textContent='You edited fields while fetching. Results were not inserted; click Fetch again when ready.';return;}
  for(const k of fields)if(result[k]&&!(k==='workplace'&&result[k]==='unknown')&&(!automatic||(k==='workplace'?previous[k]==='unknown':!previous[k].trim())))form.elements[k].value=result[k];
  status.textContent='Details fetched · '+result.method+'. Review the description and fields, then click Save to Saved jobs. Nothing has been saved yet.';
 }catch(error){if($('#job-form')===form)status.textContent=error.message+' Your existing fields were kept.';}
 finally{if(button.isConnected){button.disabled=false;button.textContent='Fetch job details';}}
}

// Debounce URL entry and ignore repeated blur/change events for the same URL.
let importFetchTimer;
document.addEventListener('input',event=>{
 if(event.target.id!=='import-job-url')return;
 clearTimeout(importFetchTimer);
 const input=event.target,form=input.form;
 importFetchTimer=setTimeout(()=>{
  if(!input.isConnected||!input.value.trim()||!input.checkValidity())return;
  const url=input.value.trim();
  if(form.dataset.autoFetchedUrl===url)return;
  form.dataset.autoFetchedUrl=url;
  fetchImportDetails(true);
 },700);
});

function mapPanel(job){
 const choices=destinations(job),start=homeOrigin(state.profile);
 return `<section class="map-panel" data-map-job="${esc(job.id)}"><h3>Location & commute</h3><p>${choices.length?'Use the listing location, or enter a verified office address.':'No office location is confirmed for this job. Enter an office address if the employer provides one.'}</p>${choices.some(c=>c.approximate)?'<p class="small-note">Listing locations can be broad eligibility regions. City-level directions are approximate; confirm the office before planning a commute.</p>':''}<label>Office address or location<input class="map-destination" maxlength="300" value="${esc(choices[0]?.value||'')}" placeholder="Office address or city"></label>${choices.length>1?`<label>Listed locations<select class="map-location-choice">${choices.map(c=>`<option value="${esc(c.value)}">${esc(c.label)}</option>`).join('')}</select></label>`:''}<label>Starting address<input class="map-origin" maxlength="300" autocomplete="street-address" value="${esc(start)}" placeholder="Save a home address in Profile or enter a start here"></label><p class="small-note">Defaults to your Profile home address. Editing it here changes only this route.</p><label>Travel mode<select class="map-mode"><option value="driving">Driving</option><option value="transit">Transit</option><option value="walking">Walking</option><option value="bicycling">Cycling</option></select></label><p class="small-note">Commute starts from ${start?'your saved '+(state.profile.home_address?'address/ZIP':'home location (approximate)'):'a home address or ZIP you add in Profile'}. Google calculates route distance and travel time; Radar does not guess mileage. Loading a map shares its location with Google.</p><div class="form-actions"><button type="button" class="secondary" data-action="map-view">Show location</button><button type="button" class="primary" data-action="map-route" ${start?'':'disabled'}>Directions from home</button></div><button type="button" class="text-button" data-action="map-profile">Edit saved home address in Profile</button><div class="map-output" role="status" aria-live="polite"></div>${state.mapsEmbedKey?'':'<p class="small-note">Maps opens in a new tab. An optional Google Maps Embed API key enables maps and routes inside Radar.</p>'}</section>`;
}
function showJobMap(button,route){
 const panel=button.closest('.map-panel'),destination=panel.querySelector('.map-destination').value.trim(),mode=panel.querySelector('.map-mode').value;
 const origin=route?panel.querySelector('.map-origin').value.trim():'';
 if(route&&!origin)throw Error('Add your commute start address or ZIP in Profile first.');
 const url=mapsUrl(destination,origin,mode),embedded=embedUrl(state.mapsEmbedKey,destination,origin,mode),output=panel.querySelector('.map-output');
 output.innerHTML=`<p><a class="secondary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open ${route?'route, distance & travel time':'location'} in Google Maps ${I('arrow')}</a></p>${embedded?`<iframe class="job-map-frame" title="${route?'Commute directions':'Job location'}" src="${esc(embedded)}" loading="lazy" referrerpolicy="origin" allowfullscreen></iframe>`:'<p>Use the Google Maps link above to view '+(route?'distance and travel time.':'the location.')+'</p>'}`;
}
document.addEventListener('change',event=>{if(event.target.classList.contains('map-location-choice')){const panel=event.target.closest('.map-panel');panel.querySelector('.map-destination').value=event.target.value;panel.querySelector('.map-output').innerHTML='';}if(event.target.matches('.map-destination,.map-mode,.map-origin'))event.target.closest('.map-panel').querySelector('.map-output').innerHTML='';});

// An address typed for a single route does not overwrite the saved Profile.
document.addEventListener('input',event=>{
 if(!event.target.matches('.map-origin'))return;
 const panel=event.target.closest('.map-panel');
 panel.querySelector('[data-action="map-route"]').disabled=!event.target.value.trim();
 panel.querySelector('.map-output').innerHTML='';
});
let memberList=[];
async function renderUsers(){
 const host=$('#page');host.innerHTML='<p role="status">Loading beta users…</p>';
 try{
  const data=await api('/admin/users');if(tab!==7||!state.identity?.isOwner||$('#page')!==host)return;
  memberList=data.users;
  host.innerHTML=`<section class="settings-card"><h2>Add a beta user</h2><p>Enter the email they use to sign in. Radar access updates immediately; no restart is needed.</p><form id="member-invite-form" class="member-invite"><label>Sign-in email<input name="email" type="email" maxlength="254" autocomplete="off" placeholder="friend@example.com" required></label><button class="primary">Add user</button></form><div class="banner"><strong>Cloudflare Access is a separate step.</strong><p>Add the same email to the existing Cloudflare Access Allow policy. Radar does not modify that policy or send an invitation email.</p><button type="button" class="secondary" data-action="copy-members">Copy approved emails for Cloudflare</button></div></section><section class="settings-card"><h2>Beta users</h2><p>Disabling access keeps the user's private workspace for a later re-enable. The owner cannot be disabled here.</p><div class="members-list">${memberList.map(user=>`<div class="member-row"><div><strong>${esc(user.email)}</strong><p>${user.isOwner?'Owner':user.enabled?'Radar access enabled':'Radar access disabled'} · ${user.registered?'Workspace created':'Not signed in yet'}</p></div>${user.isOwner?'<span class="badge">Owner</span>':`<button type="button" class="secondary" data-member="${esc(user.id)}" data-enabled="${!user.enabled}">${user.enabled?'Disable':'Enable'}</button>`}</div>`).join('')}</div><p class="small-note">This screen manages access only. It does not show another user's documents, addresses, or applications.</p></section>`;
 }catch(error){if(tab===7&&$('#page')===host)host.innerHTML=`<p role="alert">${esc(error.message)}</p>`;}
}

document.addEventListener('click',async event=>{
 const button=event.target.closest('[data-member],[data-action="copy-members"],[data-action="map-profile"]');if(!button)return;
 if(button.dataset.action==='map-profile'){$('#overlay').innerHTML='';tab=5;render();$('#profile-form input[name="home_address"]').focus();return;}
 try{
  if(button.dataset.action==='copy-members'){
   await navigator.clipboard.writeText(memberList.filter(user=>user.enabled).map(user=>user.email).join('\n'));
   toast('Approved emails copied. Paste them into your existing Cloudflare Access Allow policy.');return;
  }
  const enabled=button.dataset.enabled==='true';
  if(!enabled&&!confirm('Disable this user’s Radar access? Their workspace will be retained.'))return;
  button.disabled=true;
  await api('/admin/users/'+encodeURIComponent(button.dataset.member),{method:'PUT',body:JSON.stringify({enabled})});
  await renderUsers();toast(enabled?'Radar access enabled. Check the Cloudflare Allow policy too.':'Radar access disabled. Also remove the email from the Cloudflare policy.');
 }catch(error){toast(error.message,true);if(button.isConnected)button.disabled=false;}
});
